import 'package:flutter_test/flutter_test.dart';
import 'package:convert/convert.dart';
import 'package:soqushield/services/tx_parser.dart';

/// KAT: a real stagenet faucet transaction (txid 75a2afc0e728…, 2026-08-26)
/// paying 500 tSOQ to the derivation-KAT burner address. Full raw hex pinned
/// so the parser is exercised against node-produced bytes, not self-built ones.
const _kFaucetRawHex =
    '';

void main() {
  group('TxParser (bead m4f P2 history reconstruction)', () {
    test('parses a real node-produced segwit tx', () {
      final tx = TxParser.parse(_kFaucetRawHex);

      expect(tx.inputs.length, 1);
      expect(tx.inputs[0].prevTxid,
          'c59e6c1cdc2aefb479ce8390e8b73d8cc4dc60f4e721b1c05ff73990cf543a85');
      expect(tx.inputs[0].prevVout, 1);

      expect(tx.outputs.length, 2);
      // 500 SOQ = 50,000,000,000 sats to the KAT burner (witness v1).
      expect(tx.outputs[0].valueSat, 50000000000);
      expect(hex.encode(tx.outputs[0].scriptPubKey),
          '51208cb536d7461dcecf9fb83e8c786eadf926c2d31609274255b5d59793ca0fa594');
      // Change back to the faucet — value positive, script well-formed v1.
      expect(tx.outputs[1].valueSat, greaterThan(0));
      expect(tx.outputs[1].scriptPubKey.length, 34);
      expect(tx.outputs[1].scriptPubKey[0], 0x51);
    });

    test('send/receive classification primitives', () {
      final tx = TxParser.parse(_kFaucetRawHex);
      // From the faucet's perspective: input spends its own prevout, output 1
      // is change to itself — netting logic relies on exact script equality.
      final changeSpk = hex.encode(tx.outputs[1].scriptPubKey);
      final paidSpk = hex.encode(tx.outputs[0].scriptPubKey);
      expect(changeSpk == paidSpk, isFalse);
    });
  });
}
